window.SB_FEED_BODY=window.SB_FEED_BODY||{},Object.assign(window.SB_FEED_BODY,{"lc-u37-3":{src:"concept:32:cards:3",route:"#/stop/u37",cta:"Open this stop",title:"ab- / abs- (away from / off) · Abstemious & Abstract",body:"Abstemious (abs- + temetum = strong drink) = holding away from excess = moderate in eating and drinking. The -stemi- is hard to spell: A-B-S-T-E-M-I-O-U-S. Abstract = abs- + trahere = drawn away from the concrete = existing in thought not in physical form."},"lc-u37-4":{src:"concept:32:cards:4",route:"#/stop/u37",cta:"Open this stop",title:"ab- / abs- (away from / off) · ab- vs de- vs ex-",body:"All three move away from something. ab- = departing from. de- = going down from or reversing. ex- = out of. Abhor = shrink away from with disgust. Detest = hate thoroughly. Exclude = shut out. The prefix marks direction and intensity of the movement away."},"uq-u37-3":{src:"unit:u37:qs:3",route:"#/stop/u37",cta:"Open this stop",title:"Whose hook?",play:{q:"“To ▁▁▁ is to SCOOT and hide CONDtemptibly — the thief ▁▁▁ed with the cash.” — which word is this hook about?",opts:["abscond","aberrant","abjure","abrogate"],after:"From “ab- / abs- (away from / off)”."}},"wd-abscond":{src:"concept:32:words:0:def",route:"#/word/abscond",cta:"Open the word card",title:"abscond",roman:"a-BSKAHND",body:"run away; usually includes taking something or somebody along",clip:1},"wx-abscond":{src:"concept:32:words:0:ex",route:"#/word/abscond",cta:"Open the word card",title:"In a sentence · abscond",body:"Our neighbour's puppy absconded with my sock and buried it under the rose bushes.",clip:1},"wh-abscond":{src:"concept:32:words:0:hook",route:"#/word/abscond",cta:"Open the word card",title:"Remember it · abscond",body:"To abSCOND is to SCOOT and hide CONDtemptibly — the thief abSCONDed with the cash."},"wd-aberrant":{src:"concept:32:words:1:def",route:"#/word/aberrant",cta:"Open the word card",title:"aberrant",roman:"a-BEH-ruhnt",body:"Departing from the normal or expected course; straying from the usual type or standard.",clip:1},"wx-aberrant":{src:"concept:32:words:1:ex",route:"#/word/aberrant",cta:"Open the word card",title:"In a sentence · aberrant",body:"The biologist discovered an aberrant specimen with an unusual coloration that set it apart from every other member of the species.",clip:1},"wh-aberrant":{src:"concept:32:words:1:hook",route:"#/word/aberrant",cta:"Open the word card",title:"Remember it · aberrant",body:"AB (away) + ERR (wander) + ANT: something that wanders away from the norm"},"wo-aberrant":{src:"lore:aberrant:0",route:"#/word/aberrant",cta:"Open the word card",title:"Where it comes from · aberrant",body:"Latin aberrantem, present participle of aberrare, from ab- (away) + errare (to wander)"},"wx-abjure":{src:"concept:32:words:2:ex",route:"#/word/abjure",cta:"Open the word card",title:"In a sentence · abjure",body:"Under intense questioning, the scientist refused to abjure his groundbreaking theory despite the committee's pressure.",clip:1},"wh-abjure":{src:"concept:32:words:2:hook",route:"#/word/abjure",cta:"Open the word card",title:"Remember it · abjure",body:"To ABJURE is to swear (JURE) something AWAY — like a juror who renounces the verdict; keep the U-R-E."},"wd-abrogate":{src:"concept:32:words:3:def",route:"#/word/abrogate",cta:"Open the word card",title:"abrogate",roman:"A-bruh-gayt",body:"revoke formally",clip:1},"wx-abrogate":{src:"concept:32:words:3:ex",route:"#/word/abrogate",cta:"Open the word card",title:"In a sentence · abrogate",body:"The new government moved quickly to abrogate the outdated treaty that had been in place for over a century.",clip:1},"wh-abrogate":{src:"concept:32:words:3:hook",route:"#/word/abrogate",cta:"Open the word card",title:"Remember it · abrogate",body:"ABROgate — AB-olish + ROGue laws; a rogue leader abrogates the rules"},"wo-abrogate":{src:"lore:abrogate:0",route:"#/word/abrogate",cta:"Open the word card",title:"Where it comes from · abrogate",body:"Latin 'abrogare' = to repeal, from 'ab-' = away + 'rogare' = to ask, propose a law"},"wd-ablution":{src:"concept:32:words:4:def",route:"#/word/ablution",cta:"Open the word card",title:"ablution",roman:"uh-BLOO-shuhn",body:"the ritual washing of a priest's hands or of sacred vessels",clip:1},"wx-ablution":{src:"concept:32:words:4:ex",route:"#/word/ablution",cta:"Open the word card",title:"In a sentence · ablution",body:"Before the ceremony began, the priest performed an ablution, carefully washing his hands over a golden basin.",clip:1},"wh-ablution":{src:"concept:32:words:4:hook",route:"#/word/ablution",cta:"Open the word card",title:"Remember it · ablution",body:"ABLUTion: think 'ab-LOOT' — washing away impurities, spelled with a U not OO: ab-LU-tion."},"wo-ablution":{src:"lore:ablution:0",route:"#/word/ablution",cta:"Open the word card",title:"Where it comes from · ablution",body:"Latin ablutio = washing off (ab- away + luere to wash)"},"wd-abnegate":{src:"concept:32:words:5:def",route:"#/word/abnegate",cta:"Open the word card",title:"abnegate",roman:"AB-nih-gayt",body:"deny oneself (something); restrain, especially from indulging in some pleasure",clip:1},"wx-abnegate":{src:"concept:32:words:5:ex",route:"#/word/abnegate",cta:"Open the word card",title:"In a sentence · abnegate",body:"The monk chose to abnegate all worldly possessions before entering the monastery.",clip:1},"wh-abnegate":{src:"concept:32:words:5:hook",route:"#/word/abnegate",cta:"Open the word card",title:"Remember it · abnegate",body:"ABNEGATe = ab + NEGATE — to abnegate is to negate yourself, to push yourself AWAY (ab-)."},"wo-abnegate":{src:"lore:abnegate:0",route:"#/word/abnegate",cta:"Open the word card",title:"Where it comes from · abnegate",body:"Latin abnegare = to deny (ab- away + negare to deny)"},"wd-abstain":{src:"concept:32:words:6:def",route:"#/word/abstain",cta:"Open the word card",title:"abstain",roman:"uh-BSTAYN",body:"refrain from voting",clip:1},"wx-abstain":{src:"concept:32:words:6:ex",route:"#/word/abstain",cta:"Open the word card",title:"In a sentence · abstain",body:"I abstain from alcohol",clip:1},"wh-abstain":{src:"concept:32:words:6:hook",route:"#/word/abstain",cta:"Open the word card",title:"Remember it · abstain",body:"AbsTAIN — hold yourself away, like a stain you refuse to make: ends in -a-i-n."},"wd-abstemious":{src:"concept:32:words:7:def",route:"#/word/abstemious",cta:"Open the word card",title:"abstemious",roman:"ab-STEE-mee-uhs",body:"sparing in consumption of especially food and drink",clip:1},"wx-abstemious":{src:"concept:32:words:7:ex",route:"#/word/abstemious",cta:"Open the word card",title:"In a sentence · abstemious",body:"the pleasures of the table, never of much consequence to one naturally abstemious",clip:1},"wh-abstemious":{src:"concept:32:words:7:hook",route:"#/word/abstemious",cta:"Open the word card",title:"Remember it · abstemious",body:"An abstemious person stays away from temetum — remember the rare -emi- in the middle, not -emy-."},"wo-abstemious":{src:"lore:abstemious:0",route:"#/word/abstemious",cta:"Open the word card",title:"Where it comes from · abstemious",body:"Latin abstemius = sober (abs- = away + temetum = strong drink)"},"wd-abstinence":{src:"concept:32:words:8:def",route:"#/word/abstinence",cta:"Open the word card",title:"abstinence",roman:"A-bstuh-nuhns",body:"the trait of abstaining (especially from alcohol)",clip:1},"wx-abstinence":{src:"concept:32:words:8:ex",route:"#/word/abstinence",cta:"Open the word card",title:"In a sentence · abstinence",body:"The athlete's strict abstinence from sugary drinks helped her maintain peak performance throughout the entire season.",clip:1},"wh-abstinence":{src:"concept:32:words:8:hook",route:"#/word/abstinence",cta:"Open the word card",title:"Remember it · abstinence",body:"Abstinence ends in -ence (not -ance) — remember: it takes diligENCE to practice abstinENCE."},"wo-abstinence":{src:"lore:abstinence:0",route:"#/word/abstinence",cta:"Open the word card",title:"Where it comes from · abstinence",body:"Latin abstinentia = self-restraint (abs- = away + tenere = to hold)"},"wx-abstruse":{src:"concept:32:words:9:ex",route:"#/word/abstruse",cta:"Open the word card",title:"In a sentence · abstruse",body:"The professor's abstruse explanation of quantum mechanics left even the advanced students scratching their heads in confusion.",clip:1},"wh-abstruse":{src:"concept:32:words:9:hook",route:"#/word/abstruse",cta:"Open the word card",title:"Remember it · abstruse",body:"ABSTRUSe — ABSTRact and conFUSEd — if it's abstruse, you're confused"},"wo-abstruse":{src:"lore:abstruse:0",route:"#/word/abstruse",cta:"Open the word card",title:"Where it comes from · abstruse",body:"Latin 'abstrusus' = concealed, from 'abs-' = away + 'trudere' = to push, thrust"},"wd-abstract":{src:"concept:32:words:10:def",route:"#/word/abstract",cta:"Open the word card",title:"abstract",roman:"a-BSTRAKT",body:"a concept or idea not associated with any specific instance",clip:1},"wx-abstract":{src:"concept:32:words:10:ex",route:"#/word/abstract",cta:"Open the word card",title:"In a sentence · abstract",body:"he loved her only in the abstract--not in person",clip:1},"wh-abstract":{src:"concept:32:words:10:hook",route:"#/word/abstract",cta:"Open the word card",title:"Remember it · abstract",body:"Abstract ideas are DRAWN AWAY from reality — tractors DRAW, so abs-TRACT means drawn away."},"wd-aversion":{src:"concept:32:words:11:def",route:"#/word/aversion",cta:"Open the word card",title:"aversion",roman:"uh-VUR-zhuhn",body:"a feeling of intense dislike",clip:1},"wx-aversion":{src:"concept:32:words:11:ex",route:"#/word/aversion",cta:"Open the word card",title:"In a sentence · aversion",body:"Ella has a strong aversion to boiled cabbage and refuses to sit near it.",clip:1},"wh-aversion":{src:"concept:32:words:11:hook",route:"#/word/aversion",cta:"Open the word card",title:"Remember it · aversion",body:"An aVERSION turns you AWAY — picture VERSing someone you hate and turning your back."},"wo-aversion":{src:"lore:aversion:0",route:"#/word/aversion",cta:"Open the word card",title:"Where it comes from · aversion",body:"Latin aversio = turning away (a+vertere)"},"wd-avert":{src:"concept:32:words:12:def",route:"#/word/avert",cta:"Open the word card",title:"avert",roman:"uh-VURT",body:"prevent the occurrence of; prevent from happening",clip:1},"wx-avert":{src:"concept:32:words:12:ex",route:"#/word/avert",cta:"Open the word card",title:"In a sentence · avert",body:"Quick thinking by the driver averted a crash on the icy bridge this morning.",clip:1},"wh-avert":{src:"concept:32:words:12:hook",route:"#/word/avert",cta:"Open the word card",title:"Remember it · avert",body:"aVERT: turn away danger with VERT (turn) — like diVERT or reVERT, same turning root."},"wo-avert":{src:"lore:avert:0",route:"#/word/avert",cta:"Open the word card",title:"Where it comes from · avert",body:"Latin avertere = to turn away (a+vertere)"},"wd-aversive":{src:"concept:32:words:13:def",route:"#/word/aversive",cta:"Open the word card",title:"aversive",roman:"uh-VUR-suhv",body:"tending to repel or dissuade",clip:1},"wx-aversive":{src:"concept:32:words:13:ex",route:"#/word/aversive",cta:"Open the word card",title:"In a sentence · aversive",body:"aversive conditioning",clip:1},"wh-aversive":{src:"concept:32:words:13:hook",route:"#/word/aversive",cta:"Open the word card",title:"Remember it · aversive",body:"aVERSIVE ends in -IVE because it's actIVE in pushing you away — remember the I before VE."},"wo-aversive":{src:"lore:aversive:0",route:"#/word/aversive",cta:"Open the word card",title:"Where it comes from · aversive",body:"Latin aversus = turned away (a+vertere)"},"wd-abominate":{src:"concept:32:words:14:def",route:"#/word/abominate",cta:"Open the word card",title:"abominate",roman:"uh-BOM-ih-nayt",body:"find repugnant",clip:1},"wx-abominate":{src:"concept:32:words:14:ex",route:"#/word/abominate",cta:"Open the word card",title:"In a sentence · abominate",body:"Many people abominate cruelty to animals and work hard to prevent it.",clip:1},"wh-abominate":{src:"concept:32:words:14:hook",route:"#/word/abominate",cta:"Open the word card",title:"Remember it · abominate",body:"You abominate bad OMENS — spot 'omin' hiding inside abomINate."},"wo-abominate":{src:"lore:abominate:0",route:"#/word/abominate",cta:"Open the word card",title:"Where it comes from · abominate",body:"Latin abominari = to deprecate as an ill omen, from ab- + omen"},"wd-abscissa":{src:"concept:32:words:15:def",route:"#/word/abscissa",cta:"Open the word card",title:"abscissa",roman:"ab-SIS-ah",body:"the value of a coordinate on the horizontal axis",clip:1},"wx-abscissa":{src:"concept:32:words:15:ex",route:"#/word/abscissa",cta:"Open the word card",title:"In a sentence · abscissa",body:"In math class, we plotted each point by finding its abscissa along the horizontal axis.",clip:1},"wh-abscissa":{src:"concept:32:words:15:hook",route:"#/word/abscissa",cta:"Open the word card",title:"Remember it · abscissa",body:"abSCISSa has double-s like a pair of scissor blades — it cuts across the x-axis."},"wo-abscissa":{src:"lore:abscissa:0",route:"#/word/abscissa",cta:"Open the word card",title:"Where it comes from · abscissa",body:"Latin abscissa (linea) = cut-off line, from ab-(away)+scindere(to cut)"},"li-u38":{src:"concept:33:concept",route:"#/stop/u38",cta:"Open this stop",title:"ad- (toward / near) — the Great Assimilator",body:"Latin ad- = toward, near, in addition to. It is the most enthusiastic assimilator in Latin — it changes its final d to match whatever consonant follows, doubling it in the process. The doubled letter IS the prefix."},"lc-u38-0":{src:"concept:33:cards:0",route:"#/stop/u38",cta:"Open this stop",title:"ad- (toward / near) — the Great Assimilator · The Full Assimilation Chart",body:"ad- + consonant → double that consonant. Before c/q → ac-: acquire, acquiesce. Before f → af-: affect, affirm. Before g → ag-: aggrandize, aggravate. Before l → al-: alleviate, allure. Before n → an-: annotate, annihilate. Before p → ap-: appease, append. Before r → ar-: arraign."},"lc-u38-1":{src:"concept:33:cards:1",route:"#/stop/u38",cta:"Open this stop",title:"ad- (toward / near) — the Great Assimilator · ac- Words",body:"Acquiesce (ac- + quiescere = rest) = agree without protest. Accolade (ac- + French col = neck) = embrace/award. Acquit (ac- + quietare = set at rest) = declare not guilty. Accrue (ac- + crescere = grow) = accumulate over time. Double-c is the ac- assimilation signal."},"lc-u38-2":{src:"concept:33:cards:2",route:"#/stop/u38",cta:"Open this stop",title:"ad- (toward / near) — the Great Assimilator · al- Words",body:"Alleviate (al- + levis = light) = make lighter = ease pain. Allure (al- + lure) = draw toward with appeal. Allude (al- + ludere = play) = hint toward. Allocate (al- + locus = place) = assign toward a purpose. Double-l is the al- assimilation signal."},"lc-u38-3":{src:"concept:33:cards:3",route:"#/stop/u38",cta:"Open this stop",title:"ad- (toward / near) — the Great Assimilator · ap- Words",body:"Appease (ap- + pacare = pacify) = satisfy a demand. Approbation (ap- + probare = prove) = formal approval. Append (ap- + pendere = hang) = add on. Appropriate = ap- + proprius = take for one's own use. Double-p is the ap- assimilation signal."},"lc-u38-4":{src:"concept:33:cards:4",route:"#/stop/u38",cta:"Open this stop",title:"ad- (toward / near) — the Great Assimilator · as- and at- Words",body:"Assiduous (as- + sedere = sit) = diligently attending = persistently hardworking. Assimilate (as- + similis = like) = absorb and become like. Attenuate (at- + tenuis = thin) = reduce in force or density. Attrition (at- + terere = rub) = gradual wearing away."},"uq-u38-3":{src:"unit:u38:qs:3",route:"#/stop/u38",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ — an ▁▁▁ person is always DUE to be at their desk working” — which word is this hook about?",opts:["assiduous","acquiesce","accolade","acquit"],after:"From “ad- (toward / near) — the Great Assimilator”."}},"wd-assiduous":{src:"concept:33:words:0:def",route:"#/word/assiduous",cta:"Open the word card",title:"assiduous",roman:"uh-SIH-dwuhs",body:"marked by care and persistent effort",clip:1},"wx-assiduous":{src:"concept:33:words:0:ex",route:"#/word/assiduous",cta:"Open the word card",title:"In a sentence · assiduous",body:"The assiduous student reviewed her notes every evening and never missed a homework assignment, which is why she earned the top grade.",clip:1},"wh-assiduous":{src:"concept:33:words:0:hook",route:"#/word/assiduous",cta:"Open the word card",title:"Remember it · assiduous",body:"assiDUous — an assiduous person is always DUE to be at their desk working"},"wo-assiduous":{src:"lore:assiduous:0",route:"#/word/assiduous",cta:"Open the word card",title:"Where it comes from · assiduous",body:"Latin 'assiduus' = constantly present, from 'assidere' = to sit beside, from 'ad-' = at + 'sedere' = to sit"},"wd-accolade":{src:"concept:33:words:2:def",route:"#/word/accolade",cta:"Open the word card",title:"accolade",roman:"A-kuh-layd",body:"a tangible symbol signifying approval or distinction",clip:1},"wx-accolade":{src:"concept:33:words:2:ex",route:"#/word/accolade",cta:"Open the word card",title:"In a sentence · accolade",body:"A gold medal and a painted certificate were the accolades for our science project.",clip:1},"wh-accolade":{src:"concept:33:words:2:hook",route:"#/word/accolade",cta:"Open the word card",title:"Remember it · accolade",body:"An acCOLade is a hug around the COLlar — reward spelled with double C and ends in -lade."},"wo-accolade":{src:"lore:accolade:0",route:"#/word/accolade",cta:"Open the word card",title:"Where it comes from · accolade",body:"French accolade, from Latin collum = neck (an embrace around the neck to bestow knighthood)"},"wd-acquit":{src:"concept:33:words:3:def",route:"#/word/acquit",cta:"Open the word card",title:"acquit",roman:"uh-KWIHT",body:"pronounce not guilty of criminal charges",clip:1},"wx-acquit":{src:"concept:33:words:3:ex",route:"#/word/acquit",cta:"Open the word card",title:"In a sentence · acquit",body:"Jurors acquitted the shopkeeper once the video showed he had paid for every item.",clip:1},"wh-acquit":{src:"concept:33:words:3:hook",route:"#/word/acquit",cta:"Open the word card",title:"Remember it · acquit",body:"To acquit is to quietly free someone — keep the 'c' before 'quit' to set them free."},"wd-accrue":{src:"concept:33:words:4:def",route:"#/word/accrue",cta:"Open the word card",title:"accrue",roman:"uh-KROO",body:"grow by addition",clip:1},"wx-accrue":{src:"concept:33:words:4:ex",route:"#/word/accrue",cta:"Open the word card",title:"In a sentence · accrue",body:"The interest accrues",clip:1},"wh-accrue":{src:"concept:33:words:4:hook",route:"#/word/accrue",cta:"Open the word card",title:"Remember it · accrue",body:"Your savings accrue — the account gets a double 'c' bonus before '-rue'."},"wd-alleviate":{src:"concept:33:words:5:def",route:"#/word/alleviate",cta:"Open the word card",title:"alleviate",roman:"uh-LEE-vee-ayt",body:"provide physical relief, as from pain",clip:1},"wx-alleviate":{src:"concept:33:words:5:ex",route:"#/word/alleviate",cta:"Open the word card",title:"In a sentence · alleviate",body:"A cold cloth on his forehead alleviated Sam's headache within a few minutes.",clip:1},"wh-alleviate":{src:"concept:33:words:5:hook",route:"#/word/alleviate",cta:"Open the word card",title:"Remember it · alleviate",body:"To allevIATE, think 'a LEVY lifted' — LEVI carries the light load, ending in -ATE."},"wo-alleviate":{src:"lore:alleviate:0",route:"#/word/alleviate",cta:"Open the word card",title:"Where it comes from · alleviate",body:"Latin alleviare = to lighten, from levis = light"},"wd-allure":{src:"concept:33:words:6:def",route:"#/word/allure",cta:"Open the word card",title:"allure",roman:"uh-LUUR",body:"the power to entice or attract through personal charm",clip:1},"wx-allure":{src:"concept:33:words:6:ex",route:"#/word/allure",cta:"Open the word card",title:"In a sentence · allure",body:"Nobody could resist the allure of the puppy's hopeful eyes at the shelter gate.",clip:1},"wh-allure":{src:"concept:33:words:6:hook",route:"#/word/allure",cta:"Open the word card",title:"Remember it · allure",body:"The allure of a fishing LURE draws fish in — all-LURE ends with the very bait it describes."},"wd-allocate":{src:"concept:33:words:8:def",route:"#/word/allocate",cta:"Open the word card",title:"allocate",roman:"A-luh-kayt",body:"distribute according to a plan or set apart for a special purpose",clip:1},"wx-allocate":{src:"concept:33:words:8:ex",route:"#/word/allocate",cta:"Open the word card",title:"In a sentence · allocate",body:"I am allocating a loaf of bread to everyone on a daily basis",clip:1},"wh-allocate":{src:"concept:33:words:8:hook",route:"#/word/allocate",cta:"Open the word card",title:"Remember it · allocate",body:"ALLOCATE: to assign a LOCation — the LOC in the middle tells you it's about placing things."},"wo-allocate":{src:"lore:allocate:0",route:"#/word/allocate",cta:"Open the word card",title:"Where it comes from · allocate",body:"Latin ad = to + locus = place"},"wd-appease":{src:"concept:33:words:9:def",route:"#/word/appease",cta:"Open the word card",title:"appease",roman:"uh-PEEZ",body:"cause to be more favorably inclined; gain the good will of",clip:1},"wx-appease":{src:"concept:33:words:9:ex",route:"#/word/appease",cta:"Open the word card",title:"In a sentence · appease",body:"Hoping to appease his annoyed sister, Ravi washed her bike and made her toast.",clip:1},"wh-appease":{src:"concept:33:words:9:hook",route:"#/word/appease",cta:"Open the word card",title:"Remember it · appease",body:"AppEASE — to appease someone is to bring them EASE and PEACE; double P then EASE."},"wd-approbation":{src:"concept:33:words:10:def",route:"#/word/approbation",cta:"Open the word card",title:"approbation",roman:"a-pruh-BAY-shuhn",body:"official approval",clip:1},"wx-approbation":{src:"concept:33:words:10:ex",route:"#/word/approbation",cta:"Open the word card",title:"In a sentence · approbation",body:"The young playwright beamed with pride when she received the approbation of the theater's most respected critic.",clip:1},"wh-approbation":{src:"concept:33:words:10:hook",route:"#/word/approbation",cta:"Open the word card",title:"Remember it · approbation",body:"Approbation has 'probe' in it — the committee must PROBE a plan before giving official approval."},"wo-approbation":{src:"lore:approbation:0",route:"#/word/approbation",cta:"Open the word card",title:"Where it comes from · approbation",body:"Latin approbare = to approve, assent to"},"wd-append":{src:"concept:33:words:11:def",route:"#/word/append",cta:"Open the word card",title:"append",roman:"uh-PEHND",body:"add to the very end",clip:1},"wx-append":{src:"concept:33:words:11:ex",route:"#/word/append",cta:"Open the word card",title:"In a sentence · append",body:"He appended a glossary to his novel where he used an invented language",clip:1},"wh-append":{src:"concept:33:words:11:hook",route:"#/word/append",cta:"Open the word card",title:"Remember it · append",body:"APPEND has double P — picture hanging two P's at the end of a document."},"wd-appropriate":{src:"concept:33:words:12:def",route:"#/word/appropriate",cta:"Open the word card",title:"appropriate",roman:"uh-PROH-pree-uht",body:"give or assign a resource to a particular person or cause",clip:1},"wx-appropriate":{src:"concept:33:words:12:ex",route:"#/word/appropriate",cta:"Open the word card",title:"In a sentence · appropriate",body:"Councillors appropriated ten thousand rupees for new swings in the village playground.",clip:1},"wh-appropriate":{src:"concept:33:words:12:hook",route:"#/word/appropriate",cta:"Open the word card",title:"Remember it · appropriate",body:"Two P's are PROPER when you APPROPRIATE: ap-PROPRI-ate — the double-P is part of 'proper' ownership."},"wo-appropriate":{src:"lore:appropriate:0",route:"#/word/appropriate",cta:"Open the word card",title:"Where it comes from · appropriate",body:"Latin appropriare = to make one's own, from proprius = one's own"},"wd-attenuate":{src:"concept:33:words:13:def",route:"#/word/attenuate",cta:"Open the word card",title:"attenuate",roman:"uh-TEH-nyoo-ayt",body:"to make something weaker or less intense",clip:1},"wx-attenuate":{src:"concept:33:words:13:ex",route:"#/word/attenuate",cta:"Open the word card",title:"In a sentence · attenuate",body:"Thick curtains attenuate the traffic noise so we can sleep right through the night.",clip:1},"wh-attenuate":{src:"concept:33:words:13:hook",route:"#/word/attenuate",cta:"Open the word card",title:"Remember it · attenuate",body:"ATTENUATE makes something thin — picture a double-t tightrope getting thinner and thinner until it's a fine line."},"wo-attenuate":{src:"lore:attenuate:0",route:"#/word/attenuate",cta:"Open the word card",title:"Where it comes from · attenuate",body:"Latin attenuare = to make thin, from tenuis = thin"},"wd-attrition":{src:"concept:33:words:14:def",route:"#/word/attrition",cta:"Open the word card",title:"attrition",roman:"uh-TRIH-shuhn",body:"erosion by friction",clip:1},"wx-attrition":{src:"concept:33:words:14:ex",route:"#/word/attrition",cta:"Open the word card",title:"In a sentence · attrition",body:"The marathon's brutal heat and steep hills caused significant attrition among the runners, and by mile twenty only half of the original field remained strong enough to finish.",clip:1},"wh-attrition":{src:"concept:33:words:14:hook",route:"#/word/attrition",cta:"Open the word card",title:"Remember it · attrition",body:"atTRITion — the double-T army was ground down through attrition; keep both T's standing."},"wo-attrition":{src:"lore:attrition:0",route:"#/word/attrition",cta:"Open the word card",title:"Where it comes from · attrition",body:"Latin atterere = to rub away (ad=to + terere=to rub)"},"wd-aggrandize":{src:"concept:33:words:15:def",route:"#/word/aggrandize",cta:"Open the word card",title:"aggrandize",roman:"uh-GRA-ndeyez",body:"add details to",clip:1},"wx-aggrandize":{src:"concept:33:words:15:ex",route:"#/word/aggrandize",cta:"Open the word card",title:"In a sentence · aggrandize",body:"The politician tried to aggrandize his modest role in the project, claiming credit for ideas that weren't his.",clip:1},"wh-aggrandize":{src:"concept:33:words:15:hook",route:"#/word/aggrandize",cta:"Open the word card",title:"Remember it · aggrandize",body:"To AGGRANDIZE your GRAND plans, you need DOUBLE G to make them truly GREAT — end in -IZE."},"wo-aggrandize":{src:"lore:aggrandize:0",route:"#/word/aggrandize",cta:"Open the word card",title:"Where it comes from · aggrandize",body:"French agrandir = to make larger (Latin ad- + grandis great)"},"wd-annihilate":{src:"concept:33:words:16:def",route:"#/word/annihilate",cta:"Open the word card",title:"annihilate",roman:"uh-NEYE-uh-layt",body:"kill in large numbers",clip:1},"wx-annihilate":{src:"concept:33:words:16:ex",route:"#/word/annihilate",cta:"Open the word card",title:"In a sentence · annihilate",body:"The invading army threatened to annihilate every village in its path, leaving nothing but ash and silence.",clip:1},"wh-annihilate":{src:"concept:33:words:16:hook",route:"#/word/annihilate",cta:"Open the word card",title:"Remember it · annihilate",body:"ANNIhilate contains ANNI — double N, double L in the middle"},"wo-annihilate":{src:"lore:annihilate:0",route:"#/word/annihilate",cta:"Open the word card",title:"Where it comes from · annihilate",body:"Latin nihil = nothing"},"wd-arraign":{src:"concept:33:words:17:def",route:"#/word/arraign",cta:"Open the word card",title:"arraign",roman:"er-AYN",body:"call before a court to answer an indictment",clip:1},"wx-arraign":{src:"concept:33:words:17:ex",route:"#/word/arraign",cta:"Open the word card",title:"In a sentence · arraign",body:"The suspect was arraigned on Monday morning, and the judge read the charges aloud before setting a bail amount.",clip:1},"wh-arraign":{src:"concept:33:words:17:hook",route:"#/word/arraign",cta:"Open the word card",title:"Remember it · arraign",body:"arraIGN — contains REIGN; a king REIGNS in court where you are arraigned"},"wo-arraign":{src:"lore:arraign:0",route:"#/word/arraign",cta:"Open the word card",title:"Where it comes from · arraign",body:"Old French 'araisnier' = to address, from Latin 'ad-' = to + 'ratio' = reason/account"},"wd-affidavit":{src:"concept:33:words:18:def",route:"#/word/affidavit",cta:"Open the word card",title:"affidavit",roman:"a-fuh-DAY-vuht",body:"written declaration made under oath; a written statement sworn to be true before someone legally authorized to administer an oath",clip:1},"wx-affidavit":{src:"concept:33:words:18:ex",route:"#/word/affidavit",cta:"Open the word card",title:"In a sentence · affidavit",body:"The witness submitted an affidavit confirming she had seen the defendant at the park that afternoon.",clip:1},"wh-affidavit":{src:"concept:33:words:18:hook",route:"#/word/affidavit",cta:"Open the word card",title:"Remember it · affidavit",body:"He has stated his FAITH — affidavit ends in 'davit,' like a sworn DAVid staTEment."},"wo-affidavit":{src:"lore:affidavit:0",route:"#/word/affidavit",cta:"Open the word card",title:"Where it comes from · affidavit",body:"Latin affidavit = he has sworn on faith, from affidare = to trust"},"li-u39":{src:"concept:41:concept",route:"#/stop/u39",cta:"Open this stop",title:"-tion / -sion / -cion (action / state / result)",body:"The most common suffix in English — from Latin -tionem. Three spellings, one /shun/ sound, thousands of words. The right spelling depends on the root that precedes it."},"lc-u39-0":{src:"concept:41:cards:0",route:"#/stop/u39",cta:"Open this stop",title:"-tion / -sion / -cion (action / state / result) · The Three Spellings",body:"-tion = after most roots: exacerbation, perdition, scintillation. -sion = after d, l, n, r + vowel: extension, mansion, revision. -ssion = after stressed vowel: mission, passion, session, permission. -cion = rare: coercion, suspicion."},"lc-u39-1":{src:"concept:41:cards:1",route:"#/stop/u39",cta:"Open this stop",title:"-tion / -sion / -cion (action / state / result) · The Decision Rule",body:"Does the root end in d or se? Use -sion: extend → extension, revise → revision. Does it end in t or te? Use -tion: act → action, create → creation. Does it end in ess? Use -ssion: express → expression, suppress → suppression. The root ending is your guide."},"lc-u39-2":{src:"concept:41:cards:2",route:"#/stop/u39",cta:"Open this stop",title:"-tion / -sion / -cion (action / state / result) · -tion Spelling Patterns",body:"Before -tion, a c sometimes appears: infect → infection, connect → connection. Before -tion, a p sometimes appears: prescribe → prescription (-ption). Assume → assumption (-ption). These consonant mutations come from how Latin combined roots with the suffix."},"lc-u39-3":{src:"concept:41:cards:3",route:"#/stop/u39",cta:"Open this stop",title:"-tion / -sion / -cion (action / state / result) · High-Value Championship Words",body:"Propitiation = winning favor through a ritual act. Expiation = atoning for a wrong. Supplication = humble begging. Predilection (pre- + dilectus = chosen) = a strong preference. Juxtaposition (juxta = beside + posit) = placement side by side. All end in -tion."},"lc-u39-4":{src:"concept:41:cards:4",route:"#/stop/u39",cta:"Open this stop",title:"-tion / -sion / -cion (action / state / result) · Counting Syllables in -tion Words",body:"-tion is always ONE syllable = /shun/. Count carefully for long words: exacerbation = 5 syllables (ex·ac·er·ba·tion). Predestination = 6. Transubstantiation = 7. The Bizzing Bee Sound Trick (syllable by syllable) is essential for these long words."},"uq-u39-0":{src:"unit:u39:qs:0",route:"#/stop/u39",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “-tion / -sion / -cion (action / state / result)”?",opts:["The most common suffix in English — from Latin -tionem.",'Five Greek prefixes of size and distance — from "self" to "far," from "tiny" to "enormous." These appear in science, technology, and everyday vocabulary.',"Greek logos = word/reason/study.","Greek skopein = to look at."],after:"From “-tion / -sion / -cion (action / state / result)”."}},"uq-u39-3":{src:"unit:u39:qs:3",route:"#/stop/u39",cta:"Open this stop",title:"Whose hook?",play:{q:"“An ▁▁▁ is the bitter process of making things worse.” — which word is this hook about?",opts:["exacerbation","propitiation","supplication","predilection"],after:"From “-tion / -sion / -cion (action / state / result)”."}},"wd-exacerbation":{src:"concept:41:words:0:def",route:"#/word/exacerbation",cta:"Open the word card",title:"exacerbation",roman:"ih-gza-ser-BAY-shuhn",body:"action that makes a problem or a disease (or its symptoms) worse",clip:1},"wx-exacerbation":{src:"concept:41:words:0:ex",route:"#/word/exacerbation",cta:"Open the word card",title:"In a sentence · exacerbation",body:"Skipping his inhaler led to an exacerbation of Sam's asthma during the cross-country race.",clip:1},"wh-exacerbation":{src:"concept:41:words:0:hook",route:"#/word/exacerbation",cta:"Open the word card",title:"Remember it · exacerbation",body:"An exACERBATION is the bitter process of making things worse."},"wd-expiation":{src:"concept:41:words:4:def",route:"#/word/expiation",cta:"Open the word card",title:"expiation",roman:"ek-spee-AY-shun",body:"compensation for a wrong",clip:1},"wx-expiation":{src:"concept:41:words:4:ex",route:"#/word/expiation",cta:"Open the word card",title:"In a sentence · expiation",body:"His tireless community service was seen as expiation for the harm he had caused.",clip:1},"wh-expiation":{src:"concept:41:words:4:hook",route:"#/word/expiation",cta:"Open the word card",title:"Remember it · expiation",body:"EXPIATION is the ACTION of making amends — hear -ATION at the end, the act of atoning."},"wo-expiation":{src:"lore:expiation:0",route:"#/word/expiation",cta:"Open the word card",title:"Where it comes from · expiation",body:"Latin expiatio = atonement"},"wd-scintillation":{src:"concept:41:words:5:def",route:"#/word/scintillation",cta:"Open the word card",title:"scintillation",roman:"sin-tih-LAY-shun",body:"in physics, a flash of light that is produced in a phosphor when it absorbs a photon or ionizing particle",clip:1},"wx-scintillation":{src:"concept:41:words:5:ex",route:"#/word/scintillation",cta:"Open the word card",title:"In a sentence · scintillation",body:"The scintillation detector in the lab lit up each time a gamma ray struck its crystal surface, recording every tiny flash of energy.",clip:1},"wh-scintillation":{src:"concept:41:words:5:hook",route:"#/word/scintillation",cta:"Open the word card",title:"Remember it · scintillation",body:"SCINTILLA (spark) + ATION: the process of SPARKLING or flashing"},"wo-scintillation":{src:"lore:scintillation:0",route:"#/word/scintillation",cta:"Open the word card",title:"Where it comes from · scintillation",body:"Latin scintilla = spark"},"wd-predestination":{src:"concept:41:words:7:def",route:"#/word/predestination",cta:"Open the word card",title:"predestination",roman:"pree-deh-stuh-NAY-shuhn",body:"previous determination as if by destiny or fate",clip:1},"wx-predestination":{src:"concept:41:words:7:ex",route:"#/word/predestination",cta:"Open the word card",title:"In a sentence · predestination",body:"The preacher argued that predestination meant every soul's fate had been decided before birth.",clip:1},"wh-predestination":{src:"concept:41:words:7:hook",route:"#/word/predestination",cta:"Open the word card",title:"Remember it · predestination",body:"PreDESTINation means your DESTINY is set before you arrive at your destiNATION — all three share DESTIN."},"wo-predestination":{src:"lore:predestination:0",route:"#/word/predestination",cta:"Open the word card",title:"Where it comes from · predestination",body:"Latin praedestinare = to determine beforehand, from prae = before + destinare = to fasten"},"wd-perdition":{src:"concept:41:words:10:def",route:"#/word/perdition",cta:"Open the word card",title:"perdition",roman:"per-DIH-shun",body:"in Christianity, the abode of Satan and the forces of evil; where sinners suffer eternal punishment",clip:1},"wx-perdition":{src:"concept:41:words:10:ex",route:"#/word/perdition",cta:"Open the word card",title:"In a sentence · perdition",body:"Hurl'd headlong...To bottomless perdition, there to dwell",clip:1},"wh-perdition":{src:"concept:41:words:10:hook",route:"#/word/perdition",cta:"Open the word card",title:"Remember it · perdition",body:"PERDItion is total PERDITION — you're DONE (perdi-DONE), lost forever with a T-I-O-N ending."},"wo-perdition":{src:"lore:perdition:0",route:"#/word/perdition",cta:"Open the word card",title:"Where it comes from · perdition",body:"Latin perdere = to destroy, lose utterly"},"wd-juxtaposition":{src:"concept:41:words:12:def",route:"#/word/juxtaposition",cta:"Open the word card",title:"juxtaposition",roman:"j-uh-k-s-t-uh-p-uh-z-IH-sh-uh-n",body:"the act of placing close together",clip:1},"wx-juxtaposition":{src:"concept:41:words:12:ex",route:"#/word/juxtaposition",cta:"Open the word card",title:"In a sentence · juxtaposition",body:"it is the result of the juxtaposition of contrasting colors",clip:1},"wh-juxtaposition":{src:"concept:41:words:12:hook",route:"#/word/juxtaposition",cta:"Open the word card",title:"Remember it · juxtaposition",body:"JUXTA+POSITION — two words placed side by side, just like their meaning!"},"wo-juxtaposition":{src:"lore:juxtaposition:0",route:"#/word/juxtaposition",cta:"Open the word card",title:"Where it comes from · juxtaposition",body:"Latin 'juxta' = beside + 'positio' = placement"},"wd-obfuscation":{src:"concept:41:words:13:def",route:"#/word/obfuscation",cta:"Open the word card",title:"obfuscation",roman:"ah-bfuh-SKAY-shuhn",body:"confusion resulting from failure to understand",clip:1},"wx-obfuscation":{src:"concept:41:words:13:ex",route:"#/word/obfuscation",cta:"Open the word card",title:"In a sentence · obfuscation",body:"The politician's obfuscation made it nearly impossible to understand his actual position on the issue.",clip:1},"wh-obfuscation":{src:"concept:41:words:13:hook",route:"#/word/obfuscation",cta:"Open the word card",title:"Remember it · obfuscation",body:"OBFUSCATION: the 'sc' in the middle is deliberately murky — the word itself obscures with a cloudy 'sc' combo."},"wo-obfuscation":{src:"lore:obfuscation:0",route:"#/word/obfuscation",cta:"Open the word card",title:"Where it comes from · obfuscation",body:"Latin obfuscare = to darken, obscure"},"wd-remuneration":{src:"concept:41:words:14:def",route:"#/word/remuneration",cta:"Open the word card",title:"remuneration",roman:"rih-myoo-nuh-RAY-shuhn",body:"something that remunerates; payment or compensation for work or services",clip:1},"wx-remuneration":{src:"concept:41:words:14:ex",route:"#/word/remuneration",cta:"Open the word card",title:"In a sentence · remuneration",body:"The artist accepted the commission only after negotiating fair remuneration for the weeks of work the mural would require.",clip:1},"wh-remuneration":{src:"concept:41:words:14:hook",route:"#/word/remuneration",cta:"Open the word card",title:"Remember it · remuneration",body:"RE + MUNER + ATION — think of a MUNIFICENT reward returned"},"wo-remuneration":{src:"lore:remuneration:0",route:"#/word/remuneration",cta:"Open the word card",title:"Where it comes from · remuneration",body:"Latin remunerari = to reward; re- + munus = gift, service"},"li-u40":{src:"concept:42:concept",route:"#/stop/u40",cta:"Open this stop",title:"-ous / -ious / -eous / -uous (full of / having quality)",body:'The -ous adjective family means "full of" or "having the quality of." Choosing -ious, -eous, or -uous depends on the noun base. These endings produce some of the richest vocabulary in English.'},"lc-u40-0":{src:"concept:42:cards:0",route:"#/stop/u40",cta:"Open this stop",title:"-ous / -ious / -eous / -uous (full of / having quality) · The Four Forms",body:"-ous: enormous, famous. -ious (abstract nouns in -y or -ce): audacious, facetious. -eous (inherent quality): simultaneous, extraneous, igneous. -uous (manner or habit): assiduous, ambiguous, sensuous. Each variant has a pattern."},"lc-u40-1":{src:"concept:42:cards:1",route:"#/stop/u40",cta:"Open this stop",title:"-ous / -ious / -eous / -uous (full of / having quality) · The -ious Treasure Words — the -acious Cluster",body:"From the Latin -ax stem: perspicacious (sharply insightful), sagacious (wise), tenacious (holding on), voracious (devouring), pugnacious (fighting), loquacious (talkative), audacious (bold), vivacious (lively). All turn into -acity nouns: perspicacity, sagacity, tenacity."},"lc-u40-2":{src:"concept:42:cards:2",route:"#/stop/u40",cta:"Open this stop",title:"-ous / -ious / -eous / -uous (full of / having quality) · -eous Words",body:"Miscellaneous = of mixed kinds. Extraneous = from outside. Simultaneous = at the same time. Spontaneous = arising on its own. Igneous (ignis = fire) = formed from volcanic fire. Erroneous = containing error. Nauseous = causing nausea. These use -eous because the root has an -an- or bare -e- base."},"lc-u40-3":{src:"concept:42:cards:3",route:"#/stop/u40",cta:"Open this stop",title:"-ous / -ious / -eous / -uous (full of / having quality) · -uous Words",body:"Describe habitual manner: Assiduous = habitually diligent. Ambiguous = two-way. Conspicuous = clearly visible. Tenuous = very thin/weak. Impetuous = acting without thinking. Perspicuous = clearly and plainly expressed. Promiscuous = indiscriminately mixed. The -u- is part of the Latin stem."},"lc-u40-4":{src:"concept:42:cards:4",route:"#/stop/u40",cta:"Open this stop",title:"-ous / -ious / -eous / -uous (full of / having quality) · Spelling Traps",body:"Facetious = F-A-C-E-T-I-O-U-S — contains all five vowels A-E-I-O-U in order! A fun mnemonic. Mischievous = MIS-CHIEV-OUS (3 syllables, NOT 4). Grievous = GRIEV-OUS (not griev-i-ous). Adding an extra -i- to these is the most common error with this suffix family."},"uq-u40-0":{src:"unit:u40:qs:0",route:"#/stop/u40",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “-ous / -ious / -eous / -uous (full of / having quality)”?",opts:['The -ous adjective family means "full of" or "having the quality of." Choosing -ious, -eous, or -uous depends on the noun base.','Five Greek prefixes of size and distance — from "self" to "far," from "tiny" to "enormous." These appear in science, technology, and everyday vocabulary.',"Greek logos = word/reason/study.","Greek skopein = to look at."],after:"From “-ous / -ious / -eous / -uous (full of / having quality)”."}},"uq-u40-3":{src:"unit:u40:qs:3",route:"#/stop/u40",cta:"Open this stop",title:"Whose hook?",play:{q:"“PER-SPIC-acious: someone who sees (SPIC) through everything” — which word is this hook about?",opts:["perspicacious","sagacious","tenacious","voracious"],after:"From “-ous / -ious / -eous / -uous (full of / having quality)”."}},"wd-sagacious":{src:"concept:42:words:1:def",route:"#/word/sagacious",cta:"Open the word card",title:"sagacious",roman:"suh-GAY-shus",body:"showing acute mental discernment or being shrewd",clip:1},"wx-sagacious":{src:"concept:42:words:1:ex",route:"#/word/sagacious",cta:"Open the word card",title:"In a sentence · sagacious",body:"Sagacious as ever, Grandma read the clouds and told us to pack our raincoats.",clip:1},"wh-sagacious":{src:"concept:42:words:1:hook",route:"#/word/sagacious",cta:"Open the word card",title:"Remember it · sagacious",body:"A SAGE is wise; sagaCIOUS has SAGE inside it"},"wo-sagacious":{src:"lore:sagacious:0",route:"#/word/sagacious",cta:"Open the word card",title:"Where it comes from · sagacious",body:"Latin sagax = of quick perception, keen"},"wd-tenacious":{src:"concept:42:words:2:def",route:"#/word/tenacious",cta:"Open the word card",title:"tenacious",roman:"t-uh-n-AY-sh-uh-s",body:"means holding fast",clip:1},"wx-tenacious":{src:"concept:42:words:2:ex",route:"#/word/tenacious",cta:"Open the word card",title:"In a sentence · tenacious",body:"Despite failing her driving test twice, Leila remained tenacious in her determination to pass, practicing parallel parking every single evening until she could execute it smoothly, confidently, and without a single cone knocked over.",clip:1},"wh-tenacious":{src:"concept:42:words:2:hook",route:"#/word/tenacious",cta:"Open the word card",title:"Remember it · tenacious",body:"Tenacious holds fast to every letter — especially that sneaky I before OUS: ten-A-CI-OUS."},"wo-tenacious":{src:"lore:tenacious:0",route:"#/word/tenacious",cta:"Open the word card",title:"Where it comes from · tenacious",body:"Latin tenax = holding fast, from tenere = to hold"},"wd-voracious":{src:"concept:42:words:3:def",route:"#/word/voracious",cta:"Open the word card",title:"voracious",roman:"v-aw-r-AY-sh-uh-s",body:"excessively eager avid insatiable",clip:1},"wx-voracious":{src:"concept:42:words:3:ex",route:"#/word/voracious",cta:"Open the word card",title:"In a sentence · voracious",body:"A voracious reader, Meera finished four thick library books before the weekend ended.",clip:1},"wh-voracious":{src:"concept:42:words:3:hook",route:"#/word/voracious",cta:"Open the word card",title:"Remember it · voracious",body:"VORACIOUS: a VORACious eater devours — remember V-O-R-A-C-I-O-U-S, no T, just a ravenous C gobbling the word up."},"wo-voracious":{src:"lore:voracious:0",route:"#/word/voracious",cta:"Open the word card",title:"Where it comes from · voracious",body:"Latin vorare = to devour, swallow"},"wd-pugnacious":{src:"concept:42:words:4:def",route:"#/word/pugnacious",cta:"Open the word card",title:"pugnacious",roman:"puh-GNA-shihs",body:"tough and callous by virtue of experience",clip:1},"wx-pugnacious":{src:"concept:42:words:4:ex",route:"#/word/pugnacious",cta:"Open the word card",title:"In a sentence · pugnacious",body:"The pugnacious debater never backed down from a challenge, gleefully taking on opponents twice his age.",clip:1},"wh-pugnacious":{src:"concept:42:words:4:hook",route:"#/word/pugnacious",cta:"Open the word card",title:"Remember it · pugnacious",body:"PUGnacious people fight like a PUG dog — always scrappy!"},"wo-pugnacious":{src:"lore:pugnacious:0",route:"#/word/pugnacious",cta:"Open the word card",title:"Where it comes from · pugnacious",body:"Latin pugnax (fond of fighting) from pugnus (fist)"},"wd-audacious":{src:"concept:42:words:5:def",route:"#/word/audacious",cta:"Open the word card",title:"audacious",roman:"ah-DAY-shuhs",body:"invulnerable to fear or intimidation",clip:1},"wx-audacious":{src:"concept:42:words:5:ex",route:"#/word/audacious",cta:"Open the word card",title:"In a sentence · audacious",body:"The audacious climber scaled the sheer cliff face without ropes, impressing everyone who watched from below.",clip:1},"wh-audacious":{src:"concept:42:words:5:hook",route:"#/word/audacious",cta:"Open the word card",title:"Remember it · audacious",body:"AUDacious people DARE to be heard — like a loud AUDIO blast"},"wo-audacious":{src:"lore:audacious:0",route:"#/word/audacious",cta:"Open the word card",title:"Where it comes from · audacious",body:"Latin 'audax' = bold, daring, from 'audere' = to dare"},"wd-vivacious":{src:"concept:42:words:6:def",route:"#/word/vivacious",cta:"Open the word card",title:"vivacious",roman:"vuh-VAY-shuhs",body:"vigorous and animated",clip:1},"wx-vivacious":{src:"concept:42:words:6:ex",route:"#/word/vivacious",cta:"Open the word card",title:"In a sentence · vivacious",body:"The vivacious host bounded onto the stage with a huge smile, instantly energizing the audience with her contagious enthusiasm.",clip:1},"wh-vivacious":{src:"concept:42:words:6:hook",route:"#/word/vivacious",cta:"Open the word card",title:"Remember it · vivacious",body:"VIVACious — full of VIVA (life)!"},"wo-vivacious":{src:"lore:vivacious:0",route:"#/word/vivacious",cta:"Open the word card",title:"Where it comes from · vivacious",body:"Latin vivax = lively, from vivere = to live"},"wd-facetious":{src:"concept:42:words:7:def",route:"#/word/facetious",cta:"Open the word card",title:"facetious",roman:"f-uh-s-EE-sh-uh-s",body:"means not to be taken seriously",clip:1},"wx-facetious":{src:"concept:42:words:7:ex",route:"#/word/facetious",cta:"Open the word card",title:"In a sentence · facetious",body:"When Tyler suggested that the class should take a field trip to the moon for their science project, his teacher smiled and said he was being completely facetious and needed a more realistic idea.",clip:1},"wh-facetious":{src:"concept:42:words:7:hook",route:"#/word/facetious",cta:"Open the word card",title:"Remember it · facetious",body:"FACETIOUS contains all five vowels a-e-i-o-u in order — a facetious fact worth remembering!"},"wo-facetious":{src:"lore:facetious:0",route:"#/word/facetious",cta:"Open the word card",title:"Where it comes from · facetious",body:"Latin facetus = witty, clever"},"wd-simultaneous":{src:"concept:42:words:10:def",route:"#/word/simultaneous",cta:"Open the word card",title:"simultaneous",roman:"s-ay-m-uh-l-t-AY-n-ee-uh-s",body:"occurring or operating at the same time",clip:1},"wx-simultaneous":{src:"concept:42:words:10:ex",route:"#/word/simultaneous",cta:"Open the word card",title:"In a sentence · simultaneous",body:"Thunder and lightning seemed simultaneous, so we knew the storm was directly overhead.",clip:1},"wh-simultaneous":{src:"concept:42:words:10:hook",route:"#/word/simultaneous",cta:"Open the word card",title:"Remember it · simultaneous",body:"SIMULTANEOUS events happen at the SAME time — remember 'simul' means same time, then add the long '-taneous' tail."},"wo-simultaneous":{src:"lore:simultaneous:0",route:"#/word/simultaneous",cta:"Open the word card",title:"Where it comes from · simultaneous",body:"Latin simul = at the same time + -aneous = relating to"},"wd-extraneous":{src:"concept:42:words:11:def",route:"#/word/extraneous",cta:"Open the word card",title:"extraneous",roman:"eh-KSTRAY-nee-uhs",body:"not pertinent to the matter under consideration",clip:1},"wx-extraneous":{src:"concept:42:words:11:ex",route:"#/word/extraneous",cta:"Open the word card",title:"In a sentence · extraneous",body:"an issue extraneous to the debate",clip:1},"wh-extraneous":{src:"concept:42:words:11:hook",route:"#/word/extraneous",cta:"Open the word card",title:"Remember it · extraneous",body:"EXTRANEOUS details are FOREIGN to the topic — spell it EXTRANE+OUS, not extrAN-I-ous."},"wo-extraneous":{src:"lore:extraneous:0",route:"#/word/extraneous",cta:"Open the word card",title:"Where it comes from · extraneous",body:"Latin extraneus = external, foreign"},"wd-igneous":{src:"concept:42:words:12:def",route:"#/word/igneous",cta:"Open the word card",title:"igneous",roman:"IH-gnee-uhs",body:"produced under conditions involving intense heat",clip:1},"wx-igneous":{src:"concept:42:words:12:ex",route:"#/word/igneous",cta:"Open the word card",title:"In a sentence · igneous",body:"igneous rock is rock formed by solidification from a molten state; especially from molten magma",clip:1},"wh-igneous":{src:"concept:42:words:12:hook",route:"#/word/igneous",cta:"Open the word card",title:"Remember it · igneous",body:"IGNEous rock is full of fire — IGNite and IGNEous both start with that fiery IGN."},"wo-igneous":{src:"lore:igneous:0",route:"#/word/igneous",cta:"Open the word card",title:"Where it comes from · igneous",body:"Latin ignis = fire"},"wd-erroneous":{src:"concept:42:words:13:def",route:"#/word/erroneous",cta:"Open the word card",title:"erroneous",roman:"eh-ROH-nee-uhs",body:"containing or characterized by error",clip:1},"wx-erroneous":{src:"concept:42:words:13:ex",route:"#/word/erroneous",cta:"Open the word card",title:"In a sentence · erroneous",body:"erroneous conclusions",clip:1},"wh-erroneous":{src:"concept:42:words:13:hook",route:"#/word/erroneous",cta:"Open the word card",title:"Remember it · erroneous",body:"An erRONEous answer has ONE too many errors in your thinking."},"wo-erroneous":{src:"lore:erroneous:0",route:"#/word/erroneous",cta:"Open the word card",title:"Where it comes from · erroneous",body:"Latin errare = to wander/stray"},"wd-ambiguous":{src:"concept:42:words:15:def",route:"#/word/ambiguous",cta:"Open the word card",title:"ambiguous",roman:"a-MBIH-gyoo-uhs",body:"open to two or more interpretations; or of uncertain nature or significance; or (often) intended to mislead",clip:1},"wx-ambiguous":{src:"concept:42:words:15:ex",route:"#/word/ambiguous",cta:"Open the word card",title:"In a sentence · ambiguous",body:"Painted in a hurry, the sign was ambiguous: nobody could tell whether the pool was open.",clip:1},"wh-ambiguous":{src:"concept:42:words:15:hook",route:"#/word/ambiguous",cta:"Open the word card",title:"Remember it · ambiguous",body:"Ambiguous meaning wanders — don't drop the 'u' before '-ous': ambi-GU-ous keeps the mystery in the middle."},"wo-ambiguous":{src:"lore:ambiguous:0",route:"#/word/ambiguous",cta:"Open the word card",title:"Where it comes from · ambiguous",body:"Latin ambiguus = uncertain, from ambigere = to wander both ways"},"wd-conspicuous":{src:"concept:42:words:16:def",route:"#/word/conspicuous",cta:"Open the word card",title:"conspicuous",roman:"kuh-NSPIH-kyoo-uhs",body:"obvious to the eye or mind",clip:1},"wx-conspicuous":{src:"concept:42:words:16:ex",route:"#/word/conspicuous",cta:"Open the word card",title:"In a sentence · conspicuous",body:"a tower conspicuous at a great distance",clip:1},"wh-conspicuous":{src:"concept:42:words:16:hook",route:"#/word/conspicuous",cta:"Open the word card",title:"Remember it · conspicuous",body:"CONSpICUOUS has SPY in spirit — something so visible a spy could spot it instantly; don't forget the U before OUS."},"wo-conspicuous":{src:"lore:conspicuous:0",route:"#/word/conspicuous",cta:"Open the word card",title:"Where it comes from · conspicuous",body:"Latin conspicere = to look at, con+specere = to see"},"li-u41":{src:"concept:43:concept",route:"#/stop/u41",cta:"Open this stop",title:"-able / -ible (capable of being)",body:"Two spellings, one /uh-bul/ sound. The right choice depends on whether the root can stand alone as an English word. Championship spellers know both the rule and the exceptions."},"lc-u41-0":{src:"concept:43:cards:0",route:"#/stop/u41",cta:"Open this stop",title:"-able / -ible (capable of being) · The Main Rule",body:"Use -able when the root is a complete English word: comfort → comfortable, depend → dependable, break → breakable. Use -ible when the root is a Latin stem that cannot stand alone: aud- → audible, leg- → legible, vis- → visible, del- → indelible. Root completeness is the test."},"lc-u41-1":{src:"concept:43:cards:1",route:"#/stop/u41",cta:"Open this stop",title:"-able / -ible (capable of being) · The -ible List (Memorize These 20)",body:"contemptible, digestible, discernible, divisible, eligible, fallible, feasible, flexible, gullible, indelible, intelligible, irresistible, legible, permissible, plausible, sensible, susceptible, tangible, terrible, visible. When you cannot identify the root as a standalone English word, try -ible."},"lc-u41-2":{src:"concept:43:cards:2",route:"#/stop/u41",cta:"Open this stop",title:"-able / -ible (capable of being) · Negated -able/-ible",body:"in- + -able: incomprehensible, inscrutable, inexorable, inimitable, intractable. in- + -ible: indelible, infallible, ineligible, inflexible, irresistible. Knowing the negative prefix tells you the base suffix — and the base suffix tells you the spelling."},"lc-u41-3":{src:"concept:43:cards:3",route:"#/stop/u41",cta:"Open this stop",title:"-able / -ible (capable of being) · -able After -ce and -ge",body:"Keep the e before -able to preserve the soft sound: notice → noticeable, change → changeable, manage → manageable, knowledge → knowledgeable. Without the e, the c or g would harden. The e is the softening guard."},"lc-u41-4":{src:"concept:43:cards:4",route:"#/stop/u41",cta:"Open this stop",title:"-able / -ible (capable of being) · Championship -ible Traps",body:"Irresistible = I-R-R-E-S-I-S-T-I-B-L-E (double-r from ir- assimilation). Contemptible (capable of being contempted) vs contemptuous (showing contempt) — different suffix, different meaning. Indefatigable (in- + de- + fatigare = tire) = untiring — uses -able despite the complex root."},"uq-u41-0":{src:"unit:u41:qs:0",route:"#/stop/u41",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “-able / -ible (capable of being)”?",opts:["Two spellings, one /uh-bul/ sound.",'Five Greek prefixes of size and distance — from "self" to "far," from "tiny" to "enormous." These appear in science, technology, and everyday vocabulary.',"Greek logos = word/reason/study.","Greek skopein = to look at."],after:"From “-able / -ible (capable of being)”."}},"uq-u41-3":{src:"unit:u41:qs:3",route:"#/stop/u41",cta:"Open this stop",title:"Whose hook?",play:{q:"“An ▁▁▁ mark won't let you DELETE it — keep 'del' from 'delete' in the middle.” — which word is this hook about?",opts:["indelible","irresistible","incomprehensible","inscrutable"],after:"From “-able / -ible (capable of being)”."}},"wd-irresistible":{src:"concept:43:words:1:def",route:"#/word/irresistible",cta:"Open the word card",title:"irresistible",roman:"ih-rih-ZIH-stuh-buhl",body:"impossible to resist; overpowering",clip:1},"wx-irresistible":{src:"concept:43:words:1:ex",route:"#/word/irresistible",cta:"Open the word card",title:"In a sentence · irresistible",body:"irresistible (or resistless) impulses",clip:1},"wh-irresistible":{src:"concept:43:words:1:hook",route:"#/word/irresistible",cta:"Open the word card",title:"Remember it · irresistible",body:"Chocolate is irresistIBLE — the 'ible' is the tempting part you can't resist changing to -able."},"wo-irresistible":{src:"lore:irresistible:0",route:"#/word/irresistible",cta:"Open the word card",title:"Where it comes from · irresistible",body:"Latin resistere = to stand against"},"wd-inimitable":{src:"concept:43:words:4:def",route:"#/word/inimitable",cta:"Open the word card",title:"inimitable",roman:"ih-NIH-muh-tuh-buhl",body:"defying imitation; matchless",clip:1},"wx-inimitable":{src:"concept:43:words:4:ex",route:"#/word/inimitable",cta:"Open the word card",title:"In a sentence · inimitable",body:"The jazz musician's inimitable style blended classical harmonies with street rhythms in a way that left audiences speechless, because no other performer in the world could replicate the effortless energy she brought to every single note.",clip:1},"wh-inimitable":{src:"concept:43:words:4:hook",route:"#/word/inimitable",cta:"Open the word card",title:"Remember it · inimitable",body:"Spot IMITATE inside inIMITable — it cannot be imitated, even though imitate hides inside."},"wo-inimitable":{src:"lore:inimitable:0",route:"#/word/inimitable",cta:"Open the word card",title:"Where it comes from · inimitable",body:"Latin imitari = to imitate"},"wd-contemptible":{src:"concept:43:words:5:def",route:"#/word/contemptible",cta:"Open the word card",title:"contemptible",roman:"k-uh-n-t-EH-m-p-t-uh-b-uh-l",body:"meriting scorn and condemnation as paltry mean or vile",clip:1},"wx-contemptible":{src:"concept:43:words:5:ex",route:"#/word/contemptible",cta:"Open the word card",title:"In a sentence · contemptible",body:"The bully's contemptible behavior toward the new student shocked everyone in the cafeteria.",clip:1},"wh-contemptible":{src:"concept:43:words:5:hook",route:"#/word/contemptible",cta:"Open the word card",title:"Remember it · contemptible",body:"Contemptible ends in -IBLE not -ABLE — think: something contemptible is terrIBLE, and both share the -IBLE ending."},"wo-contemptible":{src:"lore:contemptible:0",route:"#/word/contemptible",cta:"Open the word card",title:"Where it comes from · contemptible",body:"Latin contemnere = to scorn, from con-(intensive)+temnere(to slight)"},"wd-eligible":{src:"concept:43:words:7:def",route:"#/word/eligible",cta:"Open the word card",title:"eligible",roman:"EH-luh-juh-buhl",body:"qualified for or allowed or worthy of being chosen",clip:1},"wx-eligible":{src:"concept:43:words:7:ex",route:"#/word/eligible",cta:"Open the word card",title:"In a sentence · eligible",body:"eligible to run for office",clip:1},"wh-eligible":{src:"concept:43:words:7:hook",route:"#/word/eligible",cta:"Open the word card",title:"Remember it · eligible",body:"An ELIGIBLE candidate can be chosen — spell it with '-ible' like 'possible,' because it's possibly the best choice."},"wo-eligible":{src:"lore:eligible:0",route:"#/word/eligible",cta:"Open the word card",title:"Where it comes from · eligible",body:"Latin eligere = to choose"},"wd-fallible":{src:"concept:43:words:8:def",route:"#/word/fallible",cta:"Open the word card",title:"fallible",roman:"FA-luh-buhl",body:"likely to fail or make errors",clip:1},"wx-fallible":{src:"concept:43:words:8:ex",route:"#/word/fallible",cta:"Open the word card",title:"In a sentence · fallible",body:"everyone is fallible to some degree",clip:1},"wh-fallible":{src:"concept:43:words:8:hook",route:"#/word/fallible",cta:"Open the word card",title:"Remember it · fallible",body:"FALLIBLE humans FALL and fail — double L, then IBLE, because we're capable of error."},"wo-fallible":{src:"lore:fallible:0",route:"#/word/fallible",cta:"Open the word card",title:"Where it comes from · fallible",body:"Latin fallere = to fail/deceive + -ible = capable of"},"wd-feasible":{src:"concept:43:words:9:def",route:"#/word/feasible",cta:"Open the word card",title:"feasible",roman:"f-EE-z-uh-b-uh-l",body:"capable of being done",clip:1},"wx-feasible":{src:"concept:43:words:9:ex",route:"#/word/feasible",cta:"Open the word card",title:"In a sentence · feasible",body:"The engineers decided that building a bridge across the gorge was not feasible with the current budget.",clip:1},"wh-feasible":{src:"concept:43:words:9:hook",route:"#/word/feasible",cta:"Open the word card",title:"Remember it · feasible",body:"If it's FEASIBLE, it's do-IBLE — remember the I: feasIBLE, not feasABLE."},"wo-feasible":{src:"lore:feasible:0",route:"#/word/feasible",cta:"Open the word card",title:"Where it comes from · feasible",body:"French faisable from faire = to do"},"wd-gullible":{src:"concept:43:words:10:def",route:"#/word/gullible",cta:"Open the word card",title:"gullible",roman:"GUH-luh-buhl",body:"naive and easily deceived or tricked",clip:1},"wx-gullible":{src:"concept:43:words:10:ex",route:"#/word/gullible",cta:"Open the word card",title:"In a sentence · gullible",body:"at that early age she had been gullible and in love",clip:1},"wh-gullible":{src:"concept:43:words:10:hook",route:"#/word/gullible",cta:"Open the word card",title:"Remember it · gullible",body:"GULLIBLE ends in -IBLE not -ABLE — a gullible person is easily tricked, so they pick the WRONG ending too: remember -IBLE."},"wo-gullible":{src:"lore:gullible:0",route:"#/word/gullible",cta:"Open the word card",title:"Where it comes from · gullible",body:"gull (to trick) + -ible (capable of being)"},"wd-permissible":{src:"concept:43:words:11:def",route:"#/word/permissible",cta:"Open the word card",title:"permissible",roman:"per-MIH-suh-buhl",body:"that may be permitted especially as according to rule",clip:1},"wx-permissible":{src:"concept:43:words:11:ex",route:"#/word/permissible",cta:"Open the word card",title:"In a sentence · permissible",body:"permissible behavior in school",clip:1},"wh-permissible":{src:"concept:43:words:11:hook",route:"#/word/permissible",cta:"Open the word card",title:"Remember it · permissible",body:"Is it perMISSIble? Check the MISS — perMISSIble ends in '-ible' not '-able', and you'd MISS an 'a' if you used it."},"wo-permissible":{src:"lore:permissible:0",route:"#/word/permissible",cta:"Open the word card",title:"Where it comes from · permissible",body:"Latin permittere = to allow"},"wd-tangible":{src:"concept:43:words:13:def",route:"#/word/tangible",cta:"Open the word card",title:"tangible",roman:"t-A-n-j-uh-b-uh-l",body:"perceptible by the senses especially the sense of touch; capable of being touched or felt",clip:1},"wx-tangible":{src:"concept:43:words:13:ex",route:"#/word/tangible",cta:"Open the word card",title:"In a sentence · tangible",body:"skin with a tangible roughness",clip:1},"wh-tangible":{src:"concept:43:words:13:hook",route:"#/word/tangible",cta:"Open the word card",title:"Remember it · tangible",body:"TANGIble — if you can TANG it (touch it), it's tangible"},"wo-tangible":{src:"lore:tangible:0",route:"#/word/tangible",cta:"Open the word card",title:"Where it comes from · tangible",body:"Latin tangere = to touch"},"wd-noticeable":{src:"concept:43:words:14:def",route:"#/word/noticeable",cta:"Open the word card",title:"noticeable",roman:"NOH-tuh-suh-buhl",body:"capable or worthy of being perceived",clip:1},"wx-noticeable":{src:"concept:43:words:14:ex",route:"#/word/noticeable",cta:"Open the word card",title:"In a sentence · noticeable",body:"noticeable shadows under her eyes",clip:1},"wh-noticeable":{src:"concept:43:words:14:hook",route:"#/word/noticeable",cta:"Open the word card",title:"Remember it · noticeable",body:"Keep the E in noticEable — the E wants to be NOTICED and refuses to disappear."},"wo-noticeable":{src:"lore:noticeable:0",route:"#/word/noticeable",cta:"Open the word card",title:"Where it comes from · noticeable",body:"Latin notitia = knowledge + -able = capable of"},"wd-changeable":{src:"concept:43:words:15:def",route:"#/word/changeable",cta:"Open the word card",title:"changeable",roman:"ch-AY-n-j-uh-b-uh-l",body:"liable to change or to be changed",clip:1},"wx-changeable":{src:"concept:43:words:15:ex",route:"#/word/changeable",cta:"Open the word card",title:"In a sentence · changeable",body:"The weather along the coastline proved so changeable that morning sunshine gave way to afternoon thunderstorms and then back to clear skies again, forcing the campers to repack their bags three separate times before dinner.",clip:1},"wh-changeable":{src:"concept:43:words:15:hook",route:"#/word/changeable",cta:"Open the word card",title:"Remember it · changeable",body:"CHANGEABLE keeps the E before -able — unlike most words, it REFUSES to change its E!"},"wo-changeable":{src:"lore:changeable:0",route:"#/word/changeable",cta:"Open the word card",title:"Where it comes from · changeable",body:"Old French changier = to exchange + able = capable of"},"wd-indefatigable":{src:"concept:43:words:16:def",route:"#/word/indefatigable",cta:"Open the word card",title:"indefatigable",roman:"ih-ndih-FA-tih-guh-buhl",body:"showing sustained enthusiastic action with unflagging vitality",clip:1},"wx-indefatigable":{src:"concept:43:words:16:ex",route:"#/word/indefatigable",cta:"Open the word card",title:"In a sentence · indefatigable",body:"The indefatigable athlete trained for six hours every day without ever complaining of exhaustion.",clip:1},"wh-indefatigable":{src:"concept:43:words:16:hook",route:"#/word/indefatigable",cta:"Open the word card",title:"Remember it · indefatigable",body:"In + de + FATIG(ue) + able: one who cannot be made FATIGUED"},"wo-indefatigable":{src:"lore:indefatigable:0",route:"#/word/indefatigable",cta:"Open the word card",title:"Where it comes from · indefatigable",body:"Latin fatigare = to tire or weary"},"wd-plausible":{src:"concept:43:words:17:def",route:"#/word/plausible",cta:"Open the word card",title:"plausible",roman:"PLAW-zuh-buhl",body:"apparently reasonable and valid, and truthful",clip:1},"wx-plausible":{src:"concept:43:words:17:ex",route:"#/word/plausible",cta:"Open the word card",title:"In a sentence · plausible",body:"The detective thought the suspect's alibi was plausible at first, but closer examination of the evidence revealed several inconsistencies that cast serious doubt on his story.",clip:1},"wh-plausible":{src:"concept:43:words:17:hook",route:"#/word/plausible",cta:"Open the word card",title:"Remember it · plausible",body:"A PLAUSIBLE story gets APPLAUSE — end it with -IBLE not -ABLE."},"wo-plausible":{src:"lore:plausible:0",route:"#/word/plausible",cta:"Open the word card",title:"Where it comes from · plausible",body:"Latin plausibilis = worthy of applause"},"li-u42":{src:"concept:44:concept",route:"#/stop/u42",cta:"Open this stop",title:"-ance / -ence / -ancy / -ency (state / quality)",body:"These noun suffixes create abstract nouns from adjectives. The rule: adjectives in -ant become -ance; adjectives in -ent become -ence. But French-origin words may not follow — and those are the ones in bees."},"lc-u42-0":{src:"concept:44:cards:0",route:"#/stop/u42",cta:"Open this stop",title:"-ance / -ence / -ancy / -ency (state / quality) · The Core Rule",body:"Adjective ending -ant → noun ending -ance: relevant → relevance, important → importance, defiant → defiance. Adjective ending -ent → noun ending -ence: different → difference, evident → evidence, prominent → prominence. The adjective tells you the noun."},"lc-u42-1":{src:"concept:44:cards:1",route:"#/stop/u42",cta:"Open this stop",title:"-ance / -ence / -ancy / -ency (state / quality) · High-Value -ence Words",body:"Effervescence = bubbly, sparkling quality. Eloquence = beautiful speaking. Benevolence = goodwill. Magniloquence = pompous speech. Renaissance (re- + naissance = birth) = R-E-N-A-I-S-S-A-N-C-E — double-s! Obeisance (-ance not -ence!) = respectful bow. Prescience = foreknowledge."},"lc-u42-2":{src:"concept:44:cards:2",route:"#/stop/u42",cta:"Open this stop",title:"-ance / -ence / -ancy / -ency (state / quality) · -escent = Becoming",body:"-escent = in the process of becoming. Effervescent = becoming bubbly. Adolescent = becoming an adult. Luminescent = becoming light-emitting. Convalescent = becoming well again. Incandescent = becoming glowingly hot. Quiescent = becoming quiet/still."},"lc-u42-3":{src:"concept:44:cards:3",route:"#/stop/u42",cta:"Open this stop",title:"-ance / -ence / -ancy / -ency (state / quality) · French Exceptions",body:"French-origin words may not follow the -ant/-ent rule. Nuance = -ance (from French, no -ant adjective). Vengeance = -ance (not -ence). Conscience = -ence (from con- + scire)."},"lc-u42-4":{src:"concept:44:cards:4",route:"#/stop/u42",cta:"Open this stop",title:"-ance / -ence / -ancy / -ency (state / quality) · -ancy/-ency (Dynamic Forms)",body:"These match their base adjectives: buoyant → buoyancy, truant → truancy, vacant → vacancy (all -ancy). Decent → decency, efficient → efficiency, urgent → urgency (all -ency). The dynamic forms -ancy/-ency are simply the -ance/-ence forms with the suffix -y attached to a slightly shortened base."},"uq-u42-0":{src:"unit:u42:qs:0",route:"#/stop/u42",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “-ance / -ence / -ancy / -ency (state / quality)”?",opts:["These noun suffixes create abstract nouns from adjectives.",'Five Greek prefixes of size and distance — from "self" to "far," from "tiny" to "enormous." These appear in science, technology, and everyday vocabulary.',"Greek logos = word/reason/study.","Greek skopein = to look at."],after:"From “-ance / -ence / -ancy / -ency (state / quality)”."}},"uq-u42-3":{src:"unit:u42:qs:3",route:"#/stop/u42",cta:"Open this stop",title:"Whose hook?",play:{q:"“Think 'ever fizzing': eff-EVER-ESCENCE — double 'e,' double 'f,' then bubbles rise to the end.” — which word is this hook about?",opts:["effervescence","eloquence","benevolence","obeisance"],after:"From “-ance / -ence / -ancy / -ency (state / quality)”."}},"wd-effervescence":{src:"concept:44:words:0:def",route:"#/word/effervescence",cta:"Open the word card",title:"effervescence",roman:"ef-er-VES-ents",body:"the process of bubbling as gas escapes",clip:1},"wx-effervescence":{src:"concept:44:words:0:ex",route:"#/word/effervescence",cta:"Open the word card",title:"In a sentence · effervescence",body:"The effervescence of the sparkling water tickled Maya's nose as she took her first sip.",clip:1},"wh-effervescence":{src:"concept:44:words:0:hook",route:"#/word/effervescence",cta:"Open the word card",title:"Remember it · effervescence",body:"Think 'ever fizzing': eff-EVER-ESCENCE — double 'e,' double 'f,' then bubbles rise to the end."},"wo-effervescence":{src:"lore:effervescence:0",route:"#/word/effervescence",cta:"Open the word card",title:"Where it comes from · effervescence",body:"French: effervescence (French)"},"wd-eloquence":{src:"concept:44:words:1:def",route:"#/word/eloquence",cta:"Open the word card",title:"eloquence",roman:"EH-l-uh-k-w-uh-n-s",body:"using language with fluency and aptness",clip:1},"wx-eloquence":{src:"concept:44:words:1:ex",route:"#/word/eloquence",cta:"Open the word card",title:"In a sentence · eloquence",body:"his eloquence attracted a large congregation",clip:1},"wh-eloquence":{src:"concept:44:words:1:hook",route:"#/word/eloquence",cta:"Open the word card",title:"Remember it · eloquence",body:"ELOQUENCE ends in -ENCE not -ANCE — an eloquent speaker always ENds with an impactful sENtencE."},"wo-eloquence":{src:"lore:eloquence:0",route:"#/word/eloquence",cta:"Open the word card",title:"Where it comes from · eloquence",body:"Latin eloquentia = ex+loqui = to speak out"},"wd-benevolence":{src:"concept:44:words:2:def",route:"#/word/benevolence",cta:"Open the word card",title:"benevolence",roman:"buh-NEH-vuh-luhns",body:"disposition to do good",clip:1},"wx-benevolence":{src:"concept:44:words:2:ex",route:"#/word/benevolence",cta:"Open the word card",title:"In a sentence · benevolence",body:"The community was moved by the benevolence of the woman who quietly paid off the school lunch debts of every struggling family in town.",clip:1},"wh-benevolence":{src:"concept:44:words:2:hook",route:"#/word/benevolence",cta:"Open the word card",title:"Remember it · benevolence",body:"BENEvolence ends in -ENCE, because a kind person gives e-n-c-e couragement to others."},"wo-benevolence":{src:"lore:benevolence:0",route:"#/word/benevolence",cta:"Open the word card",title:"Where it comes from · benevolence",body:"Latin bene = well + velle = to wish"},"wd-obeisance":{src:"concept:44:words:3:def",route:"#/word/obeisance",cta:"Open the word card",title:"obeisance",roman:"oh-BAY-suhns",body:"a bow or a curtsy",clip:1},"wx-obeisance":{src:"concept:44:words:3:ex",route:"#/word/obeisance",cta:"Open the word card",title:"In a sentence · obeisance",body:"The knight performed a deep obeisance before the queen before receiving his honored title.",clip:1},"wh-obeisance":{src:"concept:44:words:3:hook",route:"#/word/obeisance",cta:"Open the word card",title:"Remember it · obeisance",body:"OBEISANCE: bow and say 'oh-BAY' then add -SANCE — you obey with a bow of reverence."},"wo-obeisance":{src:"lore:obeisance:0",route:"#/word/obeisance",cta:"Open the word card",title:"Where it comes from · obeisance",body:"Old French obeissance = obedience, from obeir = to obey"},"wd-nuance":{src:"concept:44:words:4:def",route:"#/word/nuance",cta:"Open the word card",title:"nuance",roman:"n-OO-ah-n-s",body:"a subtle difference in meaning",clip:1},"wx-nuance":{src:"concept:44:words:4:ex",route:"#/word/nuance",cta:"Open the word card",title:"In a sentence · nuance",body:"without understanding the finer nuances you can't enjoy the humor",clip:1},"wh-nuance":{src:"concept:44:words:4:hook",route:"#/word/nuance",cta:"Open the word card",title:"Remember it · nuance",body:"NUANCE has no extra I — it's a subtle shade of meaning, so keep the spelling subtle and short."},"wo-nuance":{src:"lore:nuance:0",route:"#/word/nuance",cta:"Open the word card",title:"Where it comes from · nuance",body:"French nuer = to shade + -ance = state of"},"wd-vigilance":{src:"concept:44:words:5:def",route:"#/word/vigilance",cta:"Open the word card",title:"vigilance",roman:"VIH-juh-luhns",body:"the process of paying close and continuous attention",clip:1},"wx-vigilance":{src:"concept:44:words:5:ex",route:"#/word/vigilance",cta:"Open the word card",title:"In a sentence · vigilance",body:"Night after night, the shepherd's vigilance kept every lamb safe from wandering foxes.",clip:1},"wh-vigilance":{src:"concept:44:words:5:hook",route:"#/word/vigilance",cta:"Open the word card",title:"Remember it · vigilance",body:"VIGILANCE ends in -ANCE like 'dance' — stay alert and keep dancing watch!"},"wo-vigilance":{src:"lore:vigilance:0",route:"#/word/vigilance",cta:"Open the word card",title:"Where it comes from · vigilance",body:"Latin vigilare = to watch, be awake"},"wd-vengeance":{src:"concept:44:words:6:def",route:"#/word/vengeance",cta:"Open the word card",title:"vengeance",roman:"v-EH-n-j-uh-n-s",body:"means violent revenge or getting back",clip:1},"wx-vengeance":{src:"concept:44:words:6:ex",route:"#/word/vengeance",cta:"Open the word card",title:"In a sentence · vengeance",body:"Vengeance is mine; I will repay, saith the Lord",clip:1},"wh-vengeance":{src:"concept:44:words:6:hook",route:"#/word/vengeance",cta:"Open the word card",title:"Remember it · vengeance",body:"VENGE-ANCE: avenge with ANCE — remember there's a hidden G before -EANCE, like a grudge hiding inside."},"wo-vengeance":{src:"lore:vengeance:0",route:"#/word/vengeance",cta:"Open the word card",title:"Where it comes from · vengeance",body:"Latin vindicare = to avenge; French venger = to avenge"},"wd-conscience":{src:"concept:44:words:7:def",route:"#/word/conscience",cta:"Open the word card",title:"conscience",roman:"KAH-nshuhns",body:"motivation deriving logically from ethical or moral principles that govern a person's thoughts and actions",clip:1},"wx-conscience":{src:"concept:44:words:7:ex",route:"#/word/conscience",cta:"Open the word card",title:"In a sentence · conscience",body:"a person of unflagging conscience",clip:1},"wh-conscience":{src:"concept:44:words:7:hook",route:"#/word/conscience",cta:"Open the word card",title:"Remember it · conscience",body:"Your conSCIENCE uses SCIENCE to know right from wrong."},"wo-conscience":{src:"lore:conscience:0",route:"#/word/conscience",cta:"Open the word card",title:"Where it comes from · conscience",body:"Latin conscientia = shared knowledge, moral sense"},"wd-convalescent":{src:"concept:44:words:13:def",route:"#/word/convalescent",cta:"Open the word card",title:"convalescent",roman:"kah-nvuh-LEH-suhnt",body:"a person who is recovering from illness",clip:1},"wx-convalescent":{src:"concept:44:words:13:ex",route:"#/word/convalescent",cta:"Open the word card",title:"In a sentence · convalescent",body:"convalescent children are difficult to keep in bed",clip:1},"wh-convalescent":{src:"concept:44:words:13:hook",route:"#/word/convalescent",cta:"Open the word card",title:"Remember it · convalescent",body:"A convalESCENT patient is like an adolESCENT — both are slowly growing, and both end in -ESCENT."},"wo-convalescent":{src:"lore:convalescent:0",route:"#/word/convalescent",cta:"Open the word card",title:"Where it comes from · convalescent",body:"Latin convalescere = to grow strong"},"wd-buoyancy":{src:"concept:44:words:14:def",route:"#/word/buoyancy",cta:"Open the word card",title:"buoyancy",roman:"BOY-uh-nsee",body:"cheerfulness that bubbles to the surface; also the tendency of an object to float in a fluid",clip:1},"wx-buoyancy":{src:"concept:44:words:14:ex",route:"#/word/buoyancy",cta:"Open the word card",title:"In a sentence · buoyancy",body:"Even after her team lost the championship match, Priya's natural buoyancy lifted everyone's spirits within minutes.",clip:1},"wh-buoyancy":{src:"concept:44:words:14:hook",route:"#/word/buoyancy",cta:"Open the word card",title:"Remember it · buoyancy",body:"BUOYANCY—BUOY keeps things afloat; don't sink into 'bouyancy'—the U comes before O"},"wd-decency":{src:"concept:44:words:15:def",route:"#/word/decency",cta:"Open the word card",title:"decency",roman:"DEE-suh-nsee",body:"the quality of conforming to standards of propriety and morality",clip:1},"wx-decency":{src:"concept:44:words:15:ex",route:"#/word/decency",cta:"Open the word card",title:"In a sentence · decency",body:"She had the decency to apologize for her rude comment before the meeting ended.",clip:1},"wh-decency":{src:"concept:44:words:15:hook",route:"#/word/decency",cta:"Open the word card",title:"Remember it · decency",body:"DECency — decent people follow the rules, and so does this word: D-E-C-E-N-C-Y."},"wd-urgency":{src:"concept:44:words:16:def",route:"#/word/urgency",cta:"Open the word card",title:"urgency",roman:"UR-juh-nsee",body:"the state of being urgent; an earnest and insistent necessity",clip:1},"wx-urgency":{src:"concept:44:words:16:ex",route:"#/word/urgency",cta:"Open the word card",title:"In a sentence · urgency",body:"The urgency in the firefighter's voice made everyone evacuate the building without hesitation.",clip:1},"wh-urgency":{src:"concept:44:words:16:hook",route:"#/word/urgency",cta:"Open the word card",title:"Remember it · urgency",body:"URGENCY comes from URGE — a strong urge feels urgent."},"li-u43":{src:"concept:45:concept",route:"#/stop/u43",cta:"Open this stop",title:"-ity / -ness / -hood / -ship / -dom (abstract state)",body:"Five suffixes that convert other words into abstract nouns — from different linguistic origins, covering different territory. Together they create the vocabulary of qualities, conditions, and realms."},"lc-u43-0":{src:"concept:45:cards:0",route:"#/stop/u43",cta:"Open this stop",title:"-ity / -ness / -hood / -ship / -dom (abstract state) · -ity (Latin)",body:"The most formal abstract suffix from Latin -itas. Perspicacity, sagacity, audacity, mendacity, loquacity, voracity, tenacity, vivacity — all from -acious adjectives. Also: brevity (brevis = short), levity (levis = light), gravity (gravis = heavy), probity (probus = honest)."},"lc-u43-1":{src:"concept:45:cards:1",route:"#/stop/u43",cta:"Open this stop",title:"-ity / -ness / -hood / -ship / -dom (abstract state) · -ness (Old English)",body:"The most flexible abstract suffix — works with almost any adjective. Happiness, sadness, darkness (everyday). Also with complex Latinate adjectives: conscientiousness, fastidiousness, scrupulousness. When no -ity form exists, -ness is always available."},"lc-u43-2":{src:"concept:45:cards:2",route:"#/stop/u43",cta:"Open this stop",title:"-ity / -ness / -hood / -ship / -dom (abstract state) · -hood (Old English)",body:"Limited to specific life stages or communities: childhood, adulthood, knighthood, priesthood, neighborhood, falsehood (abstract!). Cannot be added freely — only to established words. The -hood suffix always implies membership in a state or condition."},"lc-u43-3":{src:"concept:45:cards:3",route:"#/stop/u43",cta:"Open this stop",title:"-ity / -ness / -hood / -ship / -dom (abstract state) · -ship (Old English)",body:"Scholarship, sportsmanship, workmanship, friendship, hardship, stewardship, ownership. Also: kinship, fellowship, penmanship. The suffix carries a sense of skill, relationship, or status. Seamanship = the skill of a seaman — both the role and the craft."},"lc-u43-4":{src:"concept:45:cards:4",route:"#/stop/u43",cta:"Open this stop",title:"-ity / -ness / -hood / -ship / -dom (abstract state) · -dom (Old English)",body:"Kingdom = realm of a king. Freedom = state of being free. Wisdom = state of being wise. Martyrdom = state of being a martyr. Used ironically for large groups: officialdom, boredom, stardom. Still actively used to coin new words in contemporary English — fandom is a modern -dom coinage."},"uq-u43-0":{src:"unit:u43:qs:0",route:"#/stop/u43",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “-ity / -ness / -hood / -ship / -dom (abstract state)”?",opts:["Five suffixes that convert other words into abstract nouns — from different linguistic origins, covering different territory.",'Five Greek prefixes of size and distance — from "self" to "far," from "tiny" to "enormous." These appear in science, technology, and everyday vocabulary.',"Greek logos = word/reason/study.","Greek skopein = to look at."],after:"From “-ity / -ness / -hood / -ship / -dom (abstract state)”."}},"uq-u43-3":{src:"unit:u43:qs:3",route:"#/stop/u43",cta:"Open this stop",title:"Whose hook?",play:{q:"“SAGA + city — a wise person's saga fills a whole city of knowledge: s-a-g-a-c-i-t-y.” — which word is this hook about?",opts:["sagacity","perspicacity","audacity","mendacity"],after:"From “-ity / -ness / -hood / -ship / -dom (abstract state)”."}},"wd-sagacity":{src:"concept:45:words:1:def",route:"#/word/sagacity",cta:"Open the word card",title:"sagacity",roman:"suh-GAS-ih-tee",body:"the mental ability to understand and discriminate between relations",clip:1},"wx-sagacity":{src:"concept:45:words:1:ex",route:"#/word/sagacity",cta:"Open the word card",title:"In a sentence · sagacity",body:"The elder's sagacity helped the community solve problems that had stumped even the youngest scholars.",clip:1},"wh-sagacity":{src:"concept:45:words:1:hook",route:"#/word/sagacity",cta:"Open the word card",title:"Remember it · sagacity",body:"SAGA + city — a wise person's saga fills a whole city of knowledge: s-a-g-a-c-i-t-y."},"wd-audacity":{src:"concept:45:words:2:def",route:"#/word/audacity",cta:"Open the word card",title:"audacity",roman:"ah-DA-suh-tee",body:"fearless daring",clip:1},"wx-audacity":{src:"concept:45:words:2:ex",route:"#/word/audacity",cta:"Open the word card",title:"In a sentence · audacity",body:"he had the audacity to question my decision",clip:1},"wh-audacity":{src:"concept:45:words:2:hook",route:"#/word/audacity",cta:"Open the word card",title:"Remember it · audacity",body:"AUDACITy: it takes AUDACI-TY — bold enough to drop an 's' that doesn't belong."},"wo-audacity":{src:"lore:audacity:0",route:"#/word/audacity",cta:"Open the word card",title:"Where it comes from · audacity",body:"Latin audax = bold, daring"},"wd-mendacity":{src:"concept:45:words:3:def",route:"#/word/mendacity",cta:"Open the word card",title:"mendacity",roman:"meh-NDA-sih-tee",body:"the tendency to be untruthful",clip:1},"wx-mendacity":{src:"concept:45:words:3:ex",route:"#/word/mendacity",cta:"Open the word card",title:"In a sentence · mendacity",body:"The journalist's report exposed the politician's long history of mendacity, revealing dozens of misleading statements.",clip:1},"wh-mendacity":{src:"concept:45:words:3:hook",route:"#/word/mendacity",cta:"Open the word card",title:"Remember it · mendacity",body:"MENDACITY: a MENDed story is a LIE — liars MEND the truth with DACity of deceit."},"wo-mendacity":{src:"lore:mendacity:0",route:"#/word/mendacity",cta:"Open the word card",title:"Where it comes from · mendacity",body:"Latin mendax = lying, mendacis = liar"},"wd-alacrity":{src:"concept:45:words:4:def",route:"#/word/alacrity",cta:"Open the word card",title:"alacrity",roman:"uh-LA-kruh-tee",body:"brisk and cheerful readiness or willingness to do something",clip:1},"wx-alacrity":{src:"concept:45:words:4:ex",route:"#/word/alacrity",cta:"Open the word card",title:"In a sentence · alacrity",body:"When the teacher announced a surprise pizza party, the students cleaned up the classroom with surprising alacrity.",clip:1},"wh-alacrity":{src:"concept:45:words:4:hook",route:"#/word/alacrity",cta:"Open the word card",title:"Remember it · alacrity",body:"alACRIty — think of ACRI (swift/sharp) — sharp eagerness"},"wo-alacrity":{src:"lore:alacrity:0",route:"#/word/alacrity",cta:"Open the word card",title:"Where it comes from · alacrity",body:"Latin 'alacritas' = alacer (lively, eager) + -itas (quality of)"},"wd-brevity":{src:"concept:45:words:5:def",route:"#/word/brevity",cta:"Open the word card",title:"brevity",roman:"BREH-vuh-tee",body:"the use of brief expressions",clip:1},"wx-brevity":{src:"concept:45:words:5:ex",route:"#/word/brevity",cta:"Open the word card",title:"In a sentence · brevity",body:"The teacher praised her essay for its brevity, noting how she expressed complex ideas in just three paragraphs.",clip:1},"wh-brevity":{src:"concept:45:words:5:hook",route:"#/word/brevity",cta:"Open the word card",title:"Remember it · brevity",body:"BREVITY: 'i' before 'ty'—brief like Shakespeare said, 'Brevity is the soul of wit.'"},"wd-levity":{src:"concept:45:words:6:def",route:"#/word/levity",cta:"Open the word card",title:"levity",roman:"LEH-vih-tee",body:"feeling an inappropriate lack of seriousness",clip:1},"wx-levity":{src:"concept:45:words:6:ex",route:"#/word/levity",cta:"Open the word card",title:"In a sentence · levity",body:"The comedian's levity helped ease the tension in the room after the long, serious debate.",clip:1},"wh-levity":{src:"concept:45:words:6:hook",route:"#/word/levity",cta:"Open the word card",title:"Remember it · levity",body:"LEVITY is lightness — like LEVITATION, it 'LEV'-itates above seriousness; no extra vowels needed."},"wo-levity":{src:"lore:levity:0",route:"#/word/levity",cta:"Open the word card",title:"Where it comes from · levity",body:"Latin levitas = lightness, from levis = light"},"wd-gravity":{src:"concept:45:words:7:def",route:"#/word/gravity",cta:"Open the word card",title:"gravity",roman:"GRA-vuh-tee",body:"in physics, the force of attraction between all masses in the universe; especially the attraction of the earth's mass for bodies near its surface; ; ; --Albert Einstein",clip:1},"wx-gravity":{src:"concept:45:words:7:ex",route:"#/word/gravity",cta:"Open the word card",title:"In a sentence · gravity",body:"the more remote the body the less the gravity",clip:1},"wh-gravity":{src:"concept:45:words:7:hook",route:"#/word/gravity",cta:"Open the word card",title:"Remember it · gravity",body:"GRAVity is so serious it could drag you to your GRAVE — GRAV starts both."},"wd-probity":{src:"concept:45:words:8:def",route:"#/word/probity",cta:"Open the word card",title:"probity",roman:"PROH-buh-tee",body:"complete and confirmed integrity; having strong moral principles",clip:1},"wx-probity":{src:"concept:45:words:8:ex",route:"#/word/probity",cta:"Open the word card",title:"In a sentence · probity",body:"in a world where financial probity may not be widespread",clip:1},"wh-probity":{src:"concept:45:words:8:hook",route:"#/word/probity",cta:"Open the word card",title:"Remember it · probity",body:"proBITY — a person of probity won't bite you dishonestly; -ITY signals a quality."},"wd-childhood":{src:"concept:45:words:11:def",route:"#/word/childhood",cta:"Open the word card",title:"childhood",roman:"CHEYE-ldhuud",body:"the time of person's life when they are a child",clip:1},"wx-childhood":{src:"concept:45:words:11:ex",route:"#/word/childhood",cta:"Open the word card",title:"In a sentence · childhood",body:"His childhood in the small mountain town shaped his love of hiking and the outdoors.",clip:1},"wh-childhood":{src:"concept:45:words:11:hook",route:"#/word/childhood",cta:"Open the word card",title:"Remember it · childhood",body:"CHILDHOOD wears a HOOD like Little Red Riding Hood — don't forget the double-O in -hood."},"wd-knighthood":{src:"concept:45:words:12:def",route:"#/word/knighthood",cta:"Open the word card",title:"knighthood",roman:"NEYE-thuud",body:"aristocrats holding the rank of knight",clip:1},"wx-knighthood":{src:"concept:45:words:12:ex",route:"#/word/knighthood",cta:"Open the word card",title:"In a sentence · knighthood",body:"The celebrated author was awarded a knighthood for his lifetime of contributions to literature.",clip:1},"wh-knighthood":{src:"concept:45:words:12:hook",route:"#/word/knighthood",cta:"Open the word card",title:"Remember it · knighthood",body:"KNIGHTHOOD is the HOOD of honor a KNIGHT wears — stack knight+hood and keep both the silent K and silent GH inside."},"wd-falsehood":{src:"concept:45:words:13:def",route:"#/word/falsehood",cta:"Open the word card",title:"falsehood",roman:"FA-lshuud",body:"a false statement",clip:1},"wx-falsehood":{src:"concept:45:words:13:ex",route:"#/word/falsehood",cta:"Open the word card",title:"In a sentence · falsehood",body:"The journalist worked tirelessly to expose every falsehood in the politician's speech.",clip:1},"wh-falsehood":{src:"concept:45:words:13:hook",route:"#/word/falsehood",cta:"Open the word card",title:"Remember it · falsehood",body:"A falsehood wears a HOOD to hide the truth—don't forget the 'e' before the hood."},"wd-scholarship":{src:"concept:45:words:14:def",route:"#/word/scholarship",cta:"Open the word card",title:"scholarship",roman:"SKAH-ler-shihp",body:"financial aid provided to a student on the basis of academic merit",clip:1},"wx-scholarship":{src:"concept:45:words:14:ex",route:"#/word/scholarship",cta:"Open the word card",title:"In a sentence · scholarship",body:"After years of staying up late to study, Priya won a full scholarship to attend her dream university tuition-free.",clip:1},"wh-scholarship":{src:"concept:45:words:14:hook",route:"#/word/scholarship",cta:"Open the word card",title:"Remember it · scholarship",body:"sCHOLARship — a SCHOLAR earns a scholarSHIP; don't forget the 'ch' that sounds like 'k.'"},"wo-scholarship":{src:"lore:scholarship:0",route:"#/word/scholarship",cta:"Open the word card",title:"Where it comes from · scholarship",body:"Greek skhole = leisure, discussion, school"},"wd-workmanship":{src:"concept:45:words:15:def",route:"#/word/workmanship",cta:"Open the word card",title:"workmanship",roman:"WUR-kmuh-nshihp",body:"skill in an occupation or trade",clip:1},"wx-workmanship":{src:"concept:45:words:15:ex",route:"#/word/workmanship",cta:"Open the word card",title:"In a sentence · workmanship",body:"The judge admired the fine workmanship of the hand-carved cabinet at the state fair competition.",clip:1},"wh-workmanship":{src:"concept:45:words:15:hook",route:"#/word/workmanship",cta:"Open the word card",title:"Remember it · workmanship",body:"WORKMANSHIP: the SHIP carries the skill of the WORKMAN — one P in SHIP sails the quality home."},"wo-workmanship":{src:"lore:workmanship:0",route:"#/word/workmanship",cta:"Open the word card",title:"Where it comes from · workmanship",body:"Old English weorc 'work' + mann 'person' + -scipe 'state or skill of.'"},"wd-stewardship":{src:"concept:45:words:16:def",route:"#/word/stewardship",cta:"Open the word card",title:"stewardship",roman:"STOO-er-dshihp",body:"the position of steward",clip:1},"wx-stewardship":{src:"concept:45:words:16:ex",route:"#/word/stewardship",cta:"Open the word card",title:"In a sentence · stewardship",body:"Under her careful stewardship, the community garden grew from a small plot into a neighborhood treasure.",clip:1},"wh-stewardship":{src:"concept:45:words:16:hook",route:"#/word/stewardship",cta:"Open the word card",title:"Remember it · stewardship",body:"STEWARDSHIP is the office of a STEWARD — a SHIP needs a steward, and the word ends in SHIP."},"wd-wisdom":{src:"concept:45:words:17:def",route:"#/word/wisdom",cta:"Open the word card",title:"wisdom",roman:"w-IH-z-d-uh-m",body:"information gained over time",clip:1}});
